const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// @generated withReleaseSigning';

/**
 * Signs release builds with the upload key, read from ~/.gradle/gradle.properties.
 *
 * android/ is regenerated by every `prebuild --clean`, so a hand edit to build.gradle would
 * silently disappear and the next AAB would be signed with the debug key — which Play rejects.
 * Appending a second `android {}` block here survives that, and avoids rewriting lines of the
 * template's own build.gradle, whose wording changes between SDK versions.
 *
 * Without the properties (any machine but the release one), release builds fall back to the
 * debug key so `expo run:android --variant release` still works for testing. `bundleRelease`
 * — the task that produces what is uploaded to Play — refuses to run instead, so a
 * debug-signed bundle cannot be produced by accident.
 */
const SNIPPET = `
${MARKER}
def hasUploadKey = project.hasProperty('KINTORE_UPLOAD_STORE_FILE')
android {
    signingConfigs {
        release {
            if (hasUploadKey) {
                storeFile file(KINTORE_UPLOAD_STORE_FILE)
                storePassword KINTORE_UPLOAD_STORE_PASSWORD
                keyAlias KINTORE_UPLOAD_KEY_ALIAS
                keyPassword KINTORE_UPLOAD_KEY_PASSWORD
            }
        }
    }
    buildTypes {
        release {
            signingConfig hasUploadKey ? signingConfigs.release : signingConfigs.debug
        }
    }
}
gradle.taskGraph.whenReady { graph ->
    if (!hasUploadKey && graph.allTasks.any { it.name == 'bundleRelease' }) {
        throw new GradleException('KINTORE_UPLOAD_* is not set in ~/.gradle/gradle.properties (docs/google-play-submission.md §3-3)')
    }
}
`;

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (config) => {
    if (!config.modResults.contents.includes(MARKER)) {
      config.modResults.contents += SNIPPET;
    }
    return config;
  });
};
